// Validate the *offline self-test* manifest generated by RiftReader's own writer.
import assert from 'node:assert/strict';
import { writeFile } from 'node:fs/promises';
import path from 'node:path';
import { Client } from '@modelcontextprotocol/client';
import { StdioClientTransport, getDefaultEnvironment } from '@modelcontextprotocol/client/stdio';

const manifest = process.argv[2];
if (!manifest) throw new Error('Pass an explicit offline self-test manifest path inside an allowed root.');
const client = new Client({ name: 'snapshot-acceptance', version: '0.3.0' });
const call = async (name, args) => {
  const r = await client.callTool({ name, arguments: args });
  assert.ok(!r.isError, JSON.stringify(r.content));
  const value = JSON.parse(r.content[0].text);
  assert.deepEqual(value, r.structuredContent);
  return value;
};
try {
  await client.connect(
    new StdioClientTransport({
      command: process.execPath,
      args: [path.resolve('dist/server.js')],
      stderr: 'inherit',
      env: {
        ...getDefaultEnvironment(),
        ...Object.fromEntries(
          ['WORKBRIDGE_ROOT', 'WORKBRIDGE_STATE_DIR']
            .filter((key) => process.env[key])
            .map((key) => [key, process.env[key]]),
        ),
      },
    }),
  );
  const report = await call('snapshot_manifest', {
    path: manifest,
    pose: 0,
    address: '0x10000000023',
    length: 12,
  });
  assert.ok(report.mapping, 'Expected self-test coordinates at base+0x23');
  const segment = report.mapping.path;
  await call('snapshot_cache', { path: segment, action: 'prepare' });
  let cache;
  for (let i = 0; i < 100; i++) {
    cache = await call('snapshot_cache', { path: segment });
    if (cache.status !== 'running') break;
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  assert.equal(cache.status, 'ready');
  const coordinates = await call('snapshot_read', {
    path: segment,
    offset: report.mapping.offset,
    type: 'f32',
    length: 12,
    baseAddress: report.mapping.baseAddress,
  });
  assert.deepEqual(coordinates.values, [100, 20, 200]);
  const matches = await call('snapshot_search', {
    path: segment,
    pattern: coordinates.hex,
    baseAddress: report.mapping.baseAddress,
  });
  assert.ok(matches.matches.some((x) => x.address === '0x10000000023'));
  const evidence = {
    testedAt: new Date().toISOString(),
    transport: 'local stdio MCP',
    manifest,
    segment,
    writer: 'RiftReader/scripts/family_snapshot_delta_analyzer.py:build_self_test_manifest',
    coordinates,
    matches,
    originalSourceUnchanged: true,
  };
  await writeFile('.local/snapshot-acceptance.json', JSON.stringify(evidence, null, 2));
  console.log(
    JSON.stringify({
      ok: true,
      manifest,
      address: coordinates.address,
      values: coordinates.values,
      matches: matches.matches.length,
      browserVerified: false,
    }),
  );
} finally {
  await client.close();
}
